import{_ as a,o as t,c as s,ae as n}from"./chunks/framework.C4zpkcTP.js";const m=JSON.parse('{"title":"AI Agent Skill","description":"Node Myanmar Payments is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly.","frontmatter":{"title":"AI Agent Skill","description":"Node Myanmar Payments is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly."},"headers":[],"relativePath":"node-myanmar-payments/ai-agent-skill.md","filePath":"node-myanmar-payments/ai-agent-skill.md"}'),i={name:"node-myanmar-payments/ai-agent-skill.md"};function l(o,e,r,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-agent-skill" tabindex="-1">AI Agent Skill <a class="header-anchor" href="#ai-agent-skill" aria-label="Permalink to &quot;AI Agent Skill&quot;">​</a></h1><p>Node Myanmar Payments is built for humans and AI agents. These docs are written for developers, and the package also ships an agent skill: a short guide that teaches coding agents such as Claude Code, Codex and Cursor how to install, configure and use Node Myanmar Payments the way it&#39;s meant to be used.</p><h2 id="installing-the-skill" tabindex="-1">Installing the skill <a class="header-anchor" href="#installing-the-skill" aria-label="Permalink to &quot;Installing the skill&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/node-myanmar-payments</span></span></code></pre></div><p>Or copy <code>skills/node-myanmar-payments</code> from the <a href="https://github.com/laranex/node-myanmar-payments" target="_blank" rel="noreferrer">repository</a> into your project&#39;s <code>.claude/skills</code> or <code>.agents/skills</code> folder. The folder is also included in the npm package, under <code>node_modules/@laranex/myanmar-payments/skills/node-myanmar-payments</code>.</p><h2 id="what-the-skill-covers" tabindex="-1">What the skill covers <a class="header-anchor" href="#what-the-skill-covers" aria-label="Permalink to &quot;What the skill covers&quot;">​</a></h2><p>Integrate Myanmar payment gateways (KBZ Pay, Wave Money, AYA Pay, Yoma MMQR, CyberSource) in a Node.js or TypeScript app with <code>@laranex/myanmar-payments</code>.</p><p>It is written from the package source and kept in the repository next to the code, so agents follow the same API, configuration and conventions these docs describe.</p><h2 id="keeping-it-current" tabindex="-1">Keeping it current <a class="header-anchor" href="#keeping-it-current" aria-label="Permalink to &quot;Keeping it current&quot;">​</a></h2><p>The skill lives in the package repository and is versioned with it, so it always describes the release you install. When you update Node Myanmar Payments, update the skill the same way you installed it.</p>',10)])])}const k=a(i,[["render",l]]);export{m as __pageData,k as default};
